import { Button } from "@/components/ui/button";
import { Provider } from "@supabase/supabase-js";

/**
 * Renders an OAuth sign-in button with a customizable provider logo and optional text.
 *
 * @param {Object} props - The props object.
 * @param {() => void} props.onClick - Function to be executed when the button is clicked.
 * @param {Provider} props.provider - The OAuth provider for the button (e.g., "google", "facebook").
 * @param {boolean} [props.showOnlyLogo=false] - Flag to show only the logo without the provider text. Defaults to false.
 *
 * @returns {JSX.Element} A styled button that displays the OAuth provider's logo and an optional "Continue with {Provider}" text.
 *
 * @example
 * <OAuthSignInButton
 *   onClick={handleGoogleSignIn}
 *   provider="google"
 * />
 *
 * @example
 * <OAuthSignInButton
 *   onClick={handleFacebookSignIn}
 *   provider="facebook"
 *   showOnlyLogo={true}
 * />
 */
export function OAuthSignInButton({
  onClick,
  provider,
  showOnlyLogo = false,
}: {
  onClick: () => void;
  provider: Provider;
  showOnlyLogo?: boolean;
}) {
  const logo = getOAuthButtonLogo(provider);
  return (
    <Button
      variant="outline"
      className="w-full"
      onClick={onClick}
    >
      <span className="mr-2">{logo}</span>
      {showOnlyLogo
        ? null
        : `Continue with ${provider.charAt(0).toUpperCase() + provider.slice(1)
        }`}
    </Button>
  );
}

